import{_ as e,o as d,c as a,ag as s}from"./chunks/framework.DHSXpJLs.js";const m=JSON.parse('{"title":"测试与调试","description":"","frontmatter":{},"headers":[],"relativePath":"development/testing.md","filePath":"development/testing.md","lastUpdated":1790781261000}'),i={name:"development/testing.md"};function o(r,t,c,p,l,n){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="测试与调试" tabindex="-1">测试与调试 <a class="header-anchor" href="#测试与调试" aria-label="Permalink to &quot;测试与调试&quot;">​</a></h1><p>开发采用 TDD：先写失败测试再写实现，测试文件和源码放同一个目录。涉及异步写盘的测试——转换队列、SSE、后台 goroutine——必须用条件等待确认落盘，禁止固定 sleep。</p><h2 id="各模块测试" tabindex="-1">各模块测试 <a class="header-anchor" href="#各模块测试" aria-label="Permalink to &quot;各模块测试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>框架</th><th>运行命令</th></tr></thead><tbody><tr><td>server</td><td>go test（含 httptest 与并发 <code>-race</code>）</td><td><code>cd server &amp;&amp; go test ./... &amp;&amp; go vet ./...</code></td></tr><tr><td>web</td><td>vitest + jsdom</td><td><code>cd web &amp;&amp; npm test</code></td></tr><tr><td>services/ifc</td><td>pytest</td><td><code>cd services/ifc &amp;&amp; uv run --group dev pytest</code></td></tr><tr><td>services/cad</td><td>pytest</td><td><code>cd services/cad &amp;&amp; uv run --group dev pytest</code></td></tr><tr><td>services/sandbox</td><td>pytest（用例配两套服务适配器）</td><td><code>cd services/sandbox &amp;&amp; uv run --group dev pytest</code></td></tr><tr><td>services/editapi</td><td>pytest（契约套件，两个服务环境各跑一遍）</td><td><code>cd services/ifc &amp;&amp; uv run --group dev pytest ../editapi/tests -q</code>（cad 同理）</td></tr><tr><td>converter</td><td>node:test</td><td><code>cd converter &amp;&amp; npm test</code></td></tr><tr><td>mcp</td><td>pytest</td><td><code>cd mcp &amp;&amp; uv run --group dev pytest</code></td></tr><tr><td>skill 打包</td><td>pytest</td><td><code>python -m pytest tests/skill/ -q</code></td></tr><tr><td>agent TUI</td><td>textual Pilot</td><td><code>tools/agent/agent --test</code></td></tr><tr><td>端到端</td><td>bash 冒烟</td><td><code>./scripts/smoke.sh</code>，需 server 运行</td></tr></tbody></table><p>server 的 18 个 PG 测试需要 <code>VIEWER_TEST_PG_DSN</code>（指向专用测试库，测试会删表），未设时自动跳过。各组件当前的用例规模随迭代变动，以仓库根 <code>AGENTS.md</code> 的组件表为准。</p><h2 id="端到端冒烟" tabindex="-1">端到端冒烟 <a class="header-anchor" href="#端到端冒烟" aria-label="Permalink to &quot;端到端冒烟&quot;">​</a></h2><p>前提是 server 已经在 8090 运行。编辑服务可达时冒烟会追加脚本编辑链路，不可达时自动跳过。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/smoke.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 成功以 smoke OK 结尾</span></span></code></pre></div><p>覆盖内容：上传样例 IFC，轮询到 ready，检查 XKT、metadata 和下载接口；Issue 的创建、列表、截图、状态流转和删除；override 写入与生效值断言；change log 的旧值新值断言；脚本管线的暂存、沙箱运行、保存 v1 和版本记录断言；最后清理。</p><h2 id="手工验收清单" tabindex="-1">手工验收清单 <a class="header-anchor" href="#手工验收清单" aria-label="Permalink to &quot;手工验收清单&quot;">​</a></h2><ol><li>打开 <code>http://localhost:5173</code>，新建项目并选类型，在 AI 对话栏让 agent 生成模型。</li><li>模型列表状态从 converting 变 ready；failed 有错误提示且可重试。</li><li>进查看器：IFC 模型能渲染，可切 web-ifc 引擎，轨道旋转、缩放、NavCube 正常；DXF 模型 Canvas 渲染正常。</li><li>模型树默认展开一层，搜索和类型过滤可用，节点能显隐，点击节点相机飞行并高亮。</li><li>属性面板折叠、搜索、复制正常；script-backed 模型点定位脚本能跳到编辑器对应行。</li><li>可见性工具、剖切滑杆、距离测量都可用。</li><li>Issue 全流程：选中构件新建，自动截图，3D 钉显示并可点击，状态流转，删除。</li><li>Diff：选 base 和 target，着色正确，展开看字段明细，清除后复位。</li></ol><p>跑出来不对的现象查<a href="/SourceAEC/guide/troubleshooting">故障排查</a>。</p><h2 id="文档与提交纪律" tabindex="-1">文档与提交纪律 <a class="header-anchor" href="#文档与提交纪律" aria-label="Permalink to &quot;文档与提交纪律&quot;">​</a></h2><ul><li>公开文档源在 <code>docs/site/</code>，是唯一信息源。改动后必须跑 <code>cd docs &amp;&amp; npm run docs:build</code>，死链会让构建失败。</li><li>改了 API 时要同步更新 <code>docs/site/public/</code> 下的公开 schema、对应参考页和契约测试，再运行文档构建。</li><li>文档涉及未交付能力时必须标注为规划，不得写不可执行的步骤。移动或删除文档后，全仓的相对链接要同步更新。</li><li>commit 用中文前缀：<code>feat:</code>、<code>fix:</code>、<code>docs:</code>、<code>ci:</code>、<code>chore:</code>。不要提交本机路径、密钥和运行时数据 <code>data/</code>。</li></ul>`,14)])])}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
